const express = require('express');
const crypto = require('crypto');
const axios = require('axios');

const app = express();
const API_KEYS = new Map();

// Load API keys from environment or secrets
function initializeKeys() {
  const keys = process.env.API_KEYS ? JSON.parse(process.env.API_KEYS) : {};
  Object.entries(keys).forEach(([name, key]) => {
    API_KEYS.set(name, key);
  });
}

initializeKeys();

// Middleware to validate API key
function validateApiKey(req, res, next) {
  const providedKey = req.headers['x-api-key'];
  if (!providedKey) {
    return res.status(401).json({ error: 'API key required' });
  }

  const clientId = req.headers['x-client-id'];
  if (!clientId) {
    return res.status(401).json({ error: 'Client ID required' });
  }

  const storedKey = API_KEYS.get(clientId);
  if (!storedKey) {
    return res.status(401).json({ error: 'Unknown client' });
  }

  // Vulnerable: character-by-character comparison leaks timing info
  let match = true;
  if (providedKey.length !== storedKey.length) {
    match = false;
  } else {
    for (let i = 0; i < providedKey.length; i++) {
      if (providedKey[i] !== storedKey[i]) {
        match = false;
        break; // Early exit leaks position of first mismatch
      }
    }
  }

  if (!match) {
    return res.status(403).json({ error: 'Invalid API key' });
  }

  req.clientId = clientId;
  next();
}

// Endpoint that fetches cloud metadata for service configuration
app.get('/api/config', validateApiKey, async (req, res) => {
  try {
    // Fetch instance metadata for dynamic configuration
    const metadataResponse = await axios.get(
      'http://169.254.169.254/latest/meta-data/iam/security-credentials/',
      { timeout: 2000, headers: { 'X-aws-ec2-metadata-token': 'required' } }
    );
    const roleName = metadataResponse.data;
    const credsResponse = await axios.get(
      `http://169.254.169.254/latest/meta-data/iam/security-credentials/${roleName}`,
      { timeout: 2000 }
    );
    res.json({ config: credsResponse.data, client: req.clientId });
  } catch (err) {
    // Fallback to static config if metadata unavailable
    res.json({ config: { region: 'us-east-1', mode: 'static' }, client: req.clientId });
  }
});

// Health check endpoint
